// Code generated by internal/behavior/gen from internal/behaviors/load. DO NOT EDIT.

package gen_test

import (
	"net/http"
	"testing"

	suite "github.com/stretchr/testify/suite"

	"github.com/osapi-io/osapi/internal/behavior/dispatch/servertest"
	load "github.com/osapi-io/osapi/internal/behaviors/load"
	"github.com/osapi-io/osapi/internal/behaviors/load/gen"
)

type APIGetPublicTestSuite struct {
	suite.Suite

	api *servertest.Harness
}

func (s *APIGetPublicTestSuite) SetupSuite() {
	s.api = servertest.New(s.T(), "internal/behaviors/load/gen/api.yaml", gen.Routes)
}

// TestGet sends GET /api/node/{hostname}/load and checks each answer's
// response.
func (s *APIGetPublicTestSuite) TestGet() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the example \"A host under a light load\" is sent, the host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/load",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"load.get",
				load.GetInput{},
				servertest.Completed("server1", `{"load_average":{"1min":0.32,"5min":0.28,"15min":0.25}}`),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","load_average":{"15min":0.25,"1min":0.32,"5min":0.28},"status":"ok"}]}`,
		},
		{
			Name: "when the example \"A host under a light load\" is broadcast, every host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/_all/load",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"_all",
				"load.get",
				load.GetInput{},
				servertest.Completed("server1", `{"load_average":{"1min":0.32,"5min":0.28,"15min":0.25}}`),
				servertest.Skipped("server2"),
				servertest.Failed("server3", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","load_average":{"15min":0.25,"1min":0.32,"5min":0.28},"status":"ok"},{"error":"unsupported","hostname":"server2","status":"skipped"},{"error":"boom","hostname":"server3","status":"failed"}]}`,
		},
		{
			Name: "when the host skips it, its row says skipped",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/load",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"load.get",
				load.GetInput{},
				servertest.Skipped("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"unsupported","hostname":"server1","status":"skipped"}]}`,
		},
		{
			Name: "when the host fails it, its row says failed",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/load",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"load.get",
				load.GetInput{},
				servertest.Failed("server1", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"boom","hostname":"server1","status":"failed"}]}`,
		},
		{
			Name: "when the host never answers, its row says timeout",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/load",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"load.get",
				load.GetInput{},
				servertest.TimedOut("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"","hostname":"server1","status":"timeout"}]}`,
		},
		{
			Name: "when the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/load",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"load.get",
				load.GetInput{},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
		{
			Name: "when broadcast and the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/_all/load",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"_all",
				"load.get",
				load.GetInput{},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
	})
}

// TestGetValidationHTTP sends requests the API refuses before any job is
// queued.
func (s *APIGetPublicTestSuite) TestGetValidationHTTP() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the target is not an agent, it is a 400",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/nowhere/load",
			},
			Token:    servertest.Read,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when the target is empty, it is a 400",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node//load",
			},
			Token:    servertest.Read,
			WantCode: http.StatusBadRequest,
		},
	})
}

// TestGetRBACHTTP sends tokens that do not grant load:read.
func (s *APIGetPublicTestSuite) TestGetRBACHTTP() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when there is no token, it is a 401",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/load",
			},
			Token:    servertest.NoToken,
			WantCode: http.StatusUnauthorized,
		},
		{
			Name: "when the token lacks load:read, it is a 403",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/load",
			},
			Token:    servertest.Lacking,
			WantCode: http.StatusForbidden,
		},
		{
			Name: "when the token has the admin role, the request runs",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/load",
			},
			Token: servertest.Admin,
			Job: servertest.Query(
				"server1",
				"load.get",
				load.GetInput{},
				servertest.Skipped("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"unsupported","hostname":"server1","status":"skipped"}]}`,
		},
	})
}

func TestAPIGetPublicTestSuite(
	t *testing.T,
) {
	suite.Run(t, new(APIGetPublicTestSuite))
}
